    [Theory]
    [InlineData("ALTER SEQUENCE s INCREMENT BY 5", "(AlterSequenceStatement name=[S] options=[(SequenceOption name=INCREMENT BY value=5)])")]
    [InlineData("ALTER SEQUENCE s NOMAXVALUE NOCYCLE CACHE 20 ORDER",
